protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the length of the time range
    long duration = end - start;

    // If the duration is less than or equal to the fetch data duration,
    // we can return a single time range with the entire duration
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, duration));
        return timeRanges;
    }

    // Otherwise, we need to split the time range into multiple time ranges
    // with a duration of FETCH_DATA_DURATION
    long remainingDuration = duration;
    long startTime = start;
    while (remainingDuration > 0) {
        long endTime = startTime + FETCH_DATA_DURATION;
        if (endTime >= end) {
            endTime = end;
        }
        timeRanges.add(new TimeRange(startTime, endTime - startTime));
        startTime = endTime;
        remainingDuration = duration - (endTime - start);
    }

    return timeRanges;
}

