public static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000000;
    long month = (timeBucket % 10000000) / 10000;
    long day = (timeBucket % 10000) / dayStep;
    long hour = (timeBucket % 100) / 100;
    long min = timeBucket % 100;
    return year * 10000000 + month * 10000 + day * dayStep + hour * 100 + min;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            if (Character.isLowSurrogate(str.charAt(i))) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 string");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

