/**
 * Enlarges this byte vector so that it can receive 'size' more bytes.
 * @param size number of additional bytes that this byte vector should be able to receive.
 */
private void enlarge(final int size) {
    // Check if there is enough space in the current buffer, and reallocate if necessary
    if (size > (buffer.length - written)) {
        // Calculate the new buffer size
        int newBufferSize = (buffer.length * 2);
        while (newBufferSize < (size + written)) {
            newBufferSize *= 2;
        }

        // Create a new buffer with the new size
        byte[] newBuffer = new byte[newBufferSize];

        // Copy the existing data from the old buffer to the new buffer
        System.arraycopy(buffer, 0, newBuffer, 0, written);

        // Update the buffer reference with the new buffer
        buffer = newBuffer;
    }
}

