public static int nextPrime(int desiredCapacity) {
    // Check if the desiredCapacity is invalid
    if (desiredCapacity < 0) {
      throw new IllegalArgumentException("Invalid desiredCapacity: " + desiredCapacity);
    }

    // Calculate the nearest prime number
    int nearestPrime = findNearestPrime(desiredCapacity);

    // Check if the nearest prime number is greater than or equal to the desired capacity
    if (nearestPrime < desiredCapacity) {
      // If not, then find the next prime number
      while (nearestPrime < desiredCapacity) {
        nearestPrime++;
        if (isPrime(nearestPrime)) {
          break;
        }
      }
    }

    return nearestPrime;
  }

  public static int findNearestPrime(int desiredCapacity) {
    // Check if the desiredCapacity is invalid
    if (desiredCapacity < 0) {
      throw new IllegalArgumentException("Invalid desiredCapacity: " + desiredCapacity);
    }

    // Find the nearest prime number by using a binary search
    int lowerBound = 0;
    int upperBound = desiredCapacity;
    while (true) {
      int mid = (lowerBound + upperBound) / 2;
      if (isPrime(mid)) {
        if (mid >= desiredCapacity) {
          return mid;
        } else {
          lowerBound = mid + 1;
        }
      } else {
        upperBound = mid - 1;
      }
    }
  }

  public static boolean isPrime(int number) {
    // Check if the number is valid
    if (number < 2 || number % 2 == 0) {
      return false;
    }

    // Check if the number is a prime number by using a sieve of Eratosthenes
    for (int i = 3; i * i <= number; i += 2) {
      if (number % i == 0) {
        return false;
      }
    }

    return true;
  }

