class StringUtils {
    public static String unescapeJava(String str) throws Exception {

        if (str == null) {
            return null;
        }

        // Step 1: Replace all backslash characters (\) that are followed by a backslash (\) with a single backslash (\\)
        str = str.replaceAll("\\\\\\\\", "\\\\");

        // Step 2: Replace all backslash characters (\) that are followed by a 'b' with a backspace character (\b)
        str = str.replaceAll("\\\\b", "\b");

        // Step 3: Replace all backslash characters (\) that are followed by a 'f' with a form feed character (\f)
        str = str.replaceAll("\\\\f", "\f");

        // Step 4: Replace all backslash characters (\) that are followed by a 'n' with a newline character (\n)
        str = str.replaceAll("\\\\n", "\n");

        // Step 5: Replace all backslash characters (\) that are followed by a 'r' with a carriage return character (\r)
        str = str.replaceAll("\\\\r", "\r");

        // Step 6: Replace all backslash characters (\) that are followed by a 't' with a tab character (\t)
        str = str.replaceAll("\\\\t", "\t");

        // Step 7: Replace all backslash characters (\) that are followed by a 'u' with the corresponding Unicode character
        Pattern pattern = Pattern.compile("\\\\u([0-9a-fA-F]{4})");
        Matcher matcher = pattern.matcher(str);
        while (matcher.find()) {
            int codePoint = Integer.parseInt(matcher.group(1), 16);
            str = str.replace(matcher.group(0), new String(new int[] {codePoint}, 0, 1));
        }

        return str;
    }
}

