 * @param constantPoolEntryIndex the index of a CONSTANT_Utf8 entry in the class's constant pooltable.
 * @param charBuffer the buffer to be used to read the string. This buffer must be sufficientlylarge. It is not automatically resized.
 * @return the String corresponding to the specified CONSTANT_Utf8 entry.
 */
final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPool.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Read the CONSTANT_Utf8 entry
    ConstantPoolEntry constantPoolEntry = constantPool[constantPoolEntryIndex];
    if (!(constantPoolEntry instanceof ConstantPoolEntry.Utf8Entry)) {
        throw new IllegalStateException("Not a CONSTANT_Utf8 entry at index " + constantPoolEntryIndex);
    }
    ConstantPoolEntry.Utf8Entry utf8Entry = (ConstantPoolEntry.Utf8Entry) constantPoolEntry;

    // Read the string
    int stringLength = utf8Entry.getLength();
    if (stringLength > charBuffer.length) {
        throw new IllegalArgumentException("The character buffer is not large enough to hold the string of length " + stringLength);
    }
    byte[] stringBytes = readBytes(utf8Entry.getStringIndex(), stringLength);
    for (int i = 0; i < stringLength; i++) {
        charBuffer[i] = (char) stringBytes[i];
    }

    return new String(charBuffer, 0, stringLength);
}

