public int readTag() throws IOException {
    int tag = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            return tag;
        }
        tag <<= 7;
        tag += b & 0x7F;
        if ((b & 0x80) == 0) {
            return tag;
        }
    }
}

